import java.util.*;
import org.kanger.ContextProductionNativeBinding.Snapshot;
import org.kanger.ContextWitnessResultTransport.Cut;
final class ContextSignedWitnessNativeMatrix {
 static int checks;static final int WORK=64000000;
 static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
 static Snapshot bind(boolean x,String s)throws Exception{return ContextSignedWitnessReceiverMatrix.bind(x,s);}
 static ContextSignedWitnessNativeBranch.Policy policy(){return new ContextSignedWitnessNativeBranch.Policy(64,8,2,WORK,64,ContextSignedWitnessReceiverMatrix.limits(16,WORK),ContextSignedWitnessUntilMatrix.local());}
 static final class Fixture {final Snapshot x,a,b;final List<Snapshot> fs;final ContextSignedWitnessNativeBranch.Policy p=policy();Fixture(boolean trusted,boolean reverse)throws Exception{x=bind(true,"!anchor(1);");a=bind(false,"!$u seed(u)&&~blocked(u);");b=bind(false,"!b(1);");List<Snapshot> m=reverse?Arrays.asList(b,a):Arrays.asList(a,b);fs=trusted?Collections.singletonList(ContextProductionNativeBinding.trusted("native-signed",m,WORK)):m;}}
 static ContextSignedWitnessNativeBranch.Receipt yes(Fixture f){ContextSignedWitnessNativeBranch.Result r=ContextSignedWitnessNativeBranch.run(f.x,f.fs,f.p);require(r.status==ContextSignedWitnessNativeBranch.Status.QUIESCENT_SUPPLIED,r.phase+": "+r.reason);require(r.output!=null&&r.rejection==null,"positive evidence only, never rejection prefix");return r.output;}
 static void positive()throws Exception{for(boolean reverse:new boolean[]{false,true}){Fixture f=new Fixture(false,reverse);ContextSignedWitnessNativeBranch.Receipt r=yes(f);require(r.x==f.x&&r.foreign.equals(f.fs)&&r.start.seeds==r.seeds&&r.seeds.frame.plan==r.plan,"all exact ingress identities retained");require(r.termination.result.stopping!=null&&r.termination.result.terminal.checks.size()==3,"actual final requalification all independent cuts");require(r.plan.plan.rows.size()==3&&r.plan.plan.signedRows==1,"whole original native rows preserved");ContextSignedWitnessNativeBranchAudit.check(r,f.x,f.fs,f.p,WORK,1);require(true,"fresh independent ingress audit capacity1");}Snapshot x=bind(true,"!$u anchor(u)&&~absent(u);"),a=bind(false,"!p(1);"),b=bind(false,"!~p(1);");ContextSignedWitnessNativeBranch.Policy p=policy();ContextSignedWitnessNativeBranch.Result independent=ContextSignedWitnessNativeBranch.run(x,Arrays.asList(a,b),p);require(independent.status==ContextSignedWitnessNativeBranch.Status.QUIESCENT_SUPPLIED,independent.phase+": "+independent.reason);require(independent.output.termination.result.terminal.checks.size()==3,"opposite independent siblings do not become a trusted commune");ContextSignedWitnessNativeBranchAudit.check(independent.output,x,Arrays.asList(a,b),p,WORK,1);require(true,"signed common Origin and opposite independent opinions freshly checked");System.out.println("SIGNED_NATIVE_INGRESS independentOrders=2 actualFinalStop=true exactOriginalSources=true directFreshAudit=true suppliedProfileOnly=true");}
 static void trusted()throws Exception{Fixture f=new Fixture(true,false);ContextSignedWitnessNativeBranch.Receipt r=yes(f);require(r.termination.result.terminal.checks.size()==2&&r.plan.plan.rows.size()==3,"trusted logical cut retains BOTH physical members");require(r.foreign.get(0).members.contains(f.a)&&r.foreign.get(0).members.contains(f.b),"no representative-member replacement");ContextSignedWitnessNativeBranchAudit.check(r,f.x,f.fs,f.p,WORK,64);require(true,"fresh exact trusted ingress audit");System.out.println("SIGNED_NATIVE_TRUSTED allPhysicalMembers=true oneLogicalCut=true noWriterAuthority=true");}
 interface Attempt{void run()throws Exception;}
 static void reject(Attempt a,String why)throws Exception{boolean failed=false;try{a.run();}catch(Exception expected){failed=true;}require(failed,why);}
 static void incomplete(ContextSignedWitnessNativeBranch.Result r,String why){require(r.status==ContextSignedWitnessNativeBranch.Status.INCOMPLETE&&r.output==null&&r.rejection==null,why+": atomic refusal, no proof prefix");}
 static void boundary()throws Exception{
  Fixture f=new Fixture(false,false);incomplete(ContextSignedWitnessNativeBranch.run(f.x,Arrays.asList(f.a,f.a),f.p),"duplicate physical foreign");incomplete(ContextSignedWitnessNativeBranch.run(f.x,Arrays.asList(f.a,bind(false,"!@u p(u)||q(u);")),f.p),"unsupported whole row");ContextSignedWitnessNativeBranch.Policy tiny=new ContextSignedWitnessNativeBranch.Policy(64,8,2,1,64,f.p.kernel,f.p.local);incomplete(ContextSignedWitnessNativeBranch.run(f.x,f.fs,tiny),"owning ingress budget");
  Snapshot x=bind(true,"!anchor(1); !@u seed(u)->blocked(u);");ContextSignedWitnessNativeBranch.Result r=ContextSignedWitnessNativeBranch.run(x,Collections.singletonList(f.a),f.p);require(r.status==ContextSignedWitnessNativeBranch.Status.REFUTED&&r.output==null&&r.rejection!=null,r.phase+": "+r.reason);require(r.rejection.initialRejection!=null&&r.rejection.start==null&&r.rejection.termination==null,"owned initial refutation has no continuation");require(r.rejection.initialRejection.checks.size()==2&&r.rejection.initialRejection.checks.get(Cut.of(f.a)).emptyProofs.stream().anyMatch(z->z.support.sources.size()==2&&z.support.sources.contains(f.a.primary.get(0).source)),"actual signed two-Source initial contradiction");ContextSignedWitnessNativeBranchAudit.check(r.rejection,x,Collections.singletonList(f.a),f.p,WORK,1);require(true,"initial refutation direct replay");
  Snapshot base=bind(true,"!anchor(1); !@u left(u)&&right(u)->p(u);"),a=bind(false,"!p(1); !left(1); !$u aa(u)&&~aside(u);"),b=bind(false,"!~p(1); !right(1); !$u bb(u)&&~bside(u);");ContextSignedWitnessNativeBranch.Result late=ContextSignedWitnessNativeBranch.run(base,Arrays.asList(a,b),f.p);require(late.status==ContextSignedWitnessNativeBranch.Status.REFUTED&&late.output==null&&late.rejection.initialRejection==null,late.phase+": "+late.reason);require(late.rejection.termination.result.terminal.checks.size()==3&&late.rejection.termination.result.terminal.checks.values().stream().flatMap(c->c.emptyProofs.stream()).anyMatch(z->z.support.sources.size()==4),"actual later all-cut four-Source contradiction");ContextSignedWitnessNativeBranchAudit.check(late.rejection,base,Arrays.asList(a,b),f.p,WORK,1);require(true,"post-barrier refutation independent ingress replay");System.out.println("SIGNED_NATIVE_BOUNDARY initialAndLaterAllCutRefutation=true unsupportedAndBudgetAtomic=true noFalseStablePrefix=true");
 }
 static void integrity()throws Exception{Fixture f=new Fixture(true,false);ContextSignedWitnessNativeBranch.Receipt r=yes(f);reject(()->ContextSignedWitnessNativeBranchAudit.check(r,f.x,f.fs,policy(),WORK,64),"exact policy owner");reject(()->ContextSignedWitnessNativeBranchAudit.check(r,bind(true,"!anchor(1);"),f.fs,f.p,WORK,64),"equal text not original X");reject(()->ContextSignedWitnessNativeBranchAudit.check(r,f.x,Collections.singletonList(f.a),f.p,WORK,64),"representative cannot replace trusted cut");reject(()->ContextSignedWitnessNativeBranchAudit.check(r,f.x,f.fs,f.p,1,64),"fresh verification work");Object old=ContextSignedWitnessBarrierMatrix.replace(r,"start",r.termination.result.output);reject(()->ContextSignedWitnessNativeBranchAudit.check(r,f.x,f.fs,f.p,WORK,64),"later scope cannot replace root");ContextSignedWitnessBarrierMatrix.replace(r,"start",old);old=ContextSignedWitnessBarrierMatrix.replace(r,"termination",null);reject(()->ContextSignedWitnessNativeBranchAudit.check(r,f.x,f.fs,f.p,WORK,64),"lost termination");ContextSignedWitnessBarrierMatrix.replace(r,"termination",old);old=ContextSignedWitnessBarrierMatrix.replace(r,"status",ContextSignedWitnessNativeBranch.Status.REFUTED);reject(()->ContextSignedWitnessNativeBranchAudit.check(r,f.x,f.fs,f.p,WORK,64),"changed verdict cannot borrow stopping evidence");ContextSignedWitnessBarrierMatrix.replace(r,"status",old);ContextSignedWitnessNativeBranchAudit.check(r,f.x,f.fs,f.p,WORK,1);require(true,"restored ledger freshly checked");System.out.println("SIGNED_NATIVE_INTEGRITY requestRootTerminationAndVerdictExact=true independentRestoration=true noAdmission=true");}
}
